:root,
.light {
  /* shadcn default — neutral */
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);

  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);

  --secondary: oklch(0.97 0 0);
  --secondary-foreground: oklch(0.205 0 0);

  --accent: oklch(0.97 0 0);
  --accent-foreground: oklch(0.205 0 0);

  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);

  --destructive: oklch(0.577 0.245 27.325);

  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: oklch(0.708 0 0);

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);

  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);

  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);

  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);

  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);

  /* Typography — set --font-geist-* in your app (see @godui/components/fonts) */
  --font-sans: var(
    --font-geist-sans,
    "Geist",
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    "Helvetica Neue",
    Arial,
    "Noto Sans",
    sans-serif
  );

  --font-serif: var(
    --font-geist-sans,
    "Geist",
    ui-serif,
    Georgia,
    Cambria,
    "Times New Roman",
    Times,
    serif
  );

  --font-mono: var(
    --font-geist-mono,
    "Geist Mono",
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Monaco,
    Consolas,
    "Liberation Mono",
    "Courier New",
    monospace
  );

  /* Radius */
  --radius: 0.625rem;

  /* Shadows */
  --shadow-2xs: 0 1px 2px rgb(0 0 0 / 0.02);

  --shadow-xs: 0 1px 3px rgb(0 0 0 / 0.04);

  --shadow-sm: 0 2px 6px rgb(0 0 0 / 0.05);

  --shadow: 0 4px 12px rgb(0 0 0 / 0.06);

  --shadow-md: 0 8px 20px rgb(0 0 0 / 0.08);

  --shadow-lg: 0 16px 32px rgb(0 0 0 / 0.1);

  --shadow-xl: 0 24px 48px rgb(0 0 0 / 0.12);

  --shadow-2xl: 0 40px 80px rgb(0 0 0 / 0.16);

  /* Syntax Highlighting */
  --syntax-plain: oklch(0.2 0.036 266);
  --syntax-punctuation: oklch(0.54 0.022 266);
  --syntax-keyword: oklch(0.52 0.19 302);
  --syntax-property: oklch(0.56 0.11 90);
  --syntax-string: oklch(0.52 0.106 168);
  --syntax-comment: oklch(0.63 0.016 266);
  --syntax-number: oklch(0.54 0.115 235);

  /* Inline code — track neutral theme tokens */
  --inline-code-bg: var(--muted);
  --inline-code-fg: var(--foreground);
  --inline-code-border: var(--border);

  /* Code blocks */
  --code-block: oklch(0.978 0 0);
  --code-block-foreground: oklch(0.205 0 0);
  --code-block-border: oklch(0.922 0 0);

  /* Search — track neutral theme tokens */
  --search-bg: var(--card);
  --search-fg: var(--muted-foreground);
  --search-border: var(--border);
  --search-kbd-bg: var(--muted);
  --search-kbd-fg: var(--muted-foreground);
  --search-placeholder: var(--muted-foreground);
  --search-highlight-bg: var(--primary);
  --search-highlight-fg: var(--primary-foreground);

  /* Theme panel — track neutral theme tokens */
  --theme-panel-bg: var(--card);
  --theme-panel-border: var(--border);
  --theme-panel-fg: var(--muted-foreground);
  --theme-panel-active-bg: var(--muted);
  --theme-panel-active-fg: var(--foreground);

  /* Z-index */
  --z-base: 0;
  --z-raised: 10;
  --z-overlay: 20;
  --z-sticky: 30;
  --z-popover: 40;
  --z-modal: 50;
  --z-toast: 60;

  /* GOD UI aliases */
  --color-bg: var(--background);
  --color-fg: var(--foreground);
  --color-border: var(--border);

  --color-primary: var(--primary);
  --color-primary-fg: var(--primary-foreground);

  --color-secondary-bg: var(--secondary);
  --color-secondary-fg: var(--secondary-foreground);

  --color-destructive: var(--destructive);
  --color-destructive-fg: oklch(1 0 0);

  /* Effects — sRGB triplets tracking --primary for rgba() consumers */
  --glow-highlight: 61, 102, 223;
  --color-primary-rgb: 61, 102, 223;

  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);

  /* GOD UI Brand — sapphire → light → divine gold */
  --god-gradient: linear-gradient(
    135deg,
    oklch(0.55 0.19 266) 0%,
    oklch(1 0 0) 50%,
    oklch(0.85 0.12 90) 100%
  );

  --god-glow:
    0 0 24px oklch(0.55 0.19 266 / 0.14), 0 0 80px oklch(0.85 0.12 90 / 0.06);

  /* Rainbow — sapphire, iris, aqua, rose, gold */
  --rainbow-1: oklch(0.55 0.19 266);
  --rainbow-2: oklch(0.68 0.16 305);
  --rainbow-3: oklch(0.82 0.1 185);
  --rainbow-4: oklch(0.78 0.12 14);
  --rainbow-5: oklch(0.8 0.13 90);

  --rainbow-speed: 2s;
}

/* Wide-gamut (P3) displays — restore the fuller chroma these tokens were
   authored with; the sRGB-clamped values above remain the fallback. */
@media (color-gamut: p3) {
  :root,
  .light {
    --syntax-string: oklch(0.52 0.13 168);
    --syntax-number: oklch(0.54 0.13 235);
  }
}

